+    pub fn flipped(self) -> Piece {
+        match self.shape {
+            Shape::Circle { .. } => self,
+            _ => Piece {
+                shape: self.shape,
+                a: self.b,
+                b: self.a,
+                reversed: !self.reversed,
+            },
