+                end: self.b,
+            },
+            Shape::Arc {
+                center,
+                radius,
+                start,
+                sweep,
+            } => {
+                let (start_angle, sweep_angle) = if self.reversed {
+                    (start + sweep, -sweep)
+                } else {
+                    (start, sweep)
+                };
