+    input.push(circle("cut", -3.0, 0.0, 1.0)); // left of the chord
+    input.push(circle("cut", 8.0, 8.0, 1.0)); // inside the bounding box, outside the arc
+    let chains = chain(&input, ChainOptions::default()).unwrap();
