+    let (_, hi) = sketch.bounds().expect("bounds");
+    common::near(hi.x, 2540.0);
+    common::near(hi.y, 1270.0);
+    common::near(sketch.chains().closed[0].area, 5000.0 * 25.4 * 25.4);
+}
